  status = case when public.passions.status = 'archived' then public.passions.status else excluded.status end,
  source = case when public.passions.source = 'legacy' then 'legacy' else excluded.source end,
  is_broad = excluded.is_broad,
  popularity = excluded.popularity,
  sort_order = excluded.sort_order,
  emoji = excluded.emoji,
  color = excluded.color,
  updated_at = now();

on conflict (id) do update set
  label = excluded.label,
  normalized_label = excluded.normalized_label,
  aliases = excluded.aliases,
  status = case when public.passions.status = 'archived' then public.passions.status else excluded.status end,
  source = case when public.passions.source = 'legacy' then 'legacy' else excluded.source end,
  is_broad = excluded.is_broad,
